let dpr=1;
function fit(){dpr=Math.min(window.devicePixelRatio||1,2);cv.width=W*dpr;cv.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);}
const stageWrap=document.getElementById('stageWrap');
function layoutStage(){const aw=stageWrap.clientWidth||10,ah=stageWrap.clientHeight||10,ratio=W/H;let cw=aw,ch=aw/ratio;if(ch>ah){ch=ah;cw=ah*ratio;}const pad=8;cw=Math.max(10,cw-pad);ch=Math.max(10,ch-pad);cv.style.width=Math.floor(cw)+'px';cv.style.height=Math.floor(ch)+'px';}
new ResizeObserver(()=>{fit();layoutStage();}).observe(stageWrap);
addEventListener('orientationchange',()=>setTimeout(()=>{fit();layoutStage();},80));
fit();
const GLOWS={};
function makeGlow(c){const cc=document.createElement('canvas');cc.width=cc.height=64;const g=cc.getContext('2d');let r,gg,b;if(c[0]==='#'){const n=parseInt(c.slice(1),16);r=n>>16&255;gg=n>>8&255;b=n&255;}else{const p=c.split(',');r=+p[0];gg=+p[1];b=+p[2];}const gr=g.createRadialGradient(32,32,0,32,32,32);gr.addColorStop(0,'rgba('+r+','+gg+','+b+',.9)');gr.addColorStop(.45,'rgba('+r+','+gg+','+b+',.32)');gr.addColorStop(1,'rgba('+r+','+gg+','+b+',0)');g.fillStyle=gr;g.fillRect(0,0,64,64);return cc;}
function drawGlow(g,x,y,r,c,a){let s=GLOWS[c];if(!s)s=GLOWS[c]=makeGlow(c);if(a!=null&&a<1){const p=g.globalAlpha;g.globalAlpha=p*a;g.drawImage(s,x-r,y-r,r+r,r+r);g.globalAlpha=p;}else g.drawImage(s,x-r,y-r,r+r,r+r);}
const pPool=[],fPool=[];
function getP(){return pPool.length?pPool.pop():{};}
function getF(){return fPool.length?fPool.pop():{};}
function P(x,y,vx,vy,dur,c,r,gv){const o=getP();o.x=x;o.y=y;o.vx=vx;o.vy=vy;o.t=0;o.dur=dur;o.c='rgb('+c+')';o.r=r;o.g=gv||0;particles.push(o);}
function pushF(x,y,txt,c,dur,big){const o=getF();o.x=x;o.y=y;o.txt=txt;o.c=c;o.t=0;o.dur=dur;o.big=!!big;floaters.push(o);}
function pruneParticles(){let w=0;for(let i=0;i<particles.length;i++){const p=particles[i];if(p.t<p.dur)particles[w++]=p;else pPool.push(p);}particles.length=w;}
function pruneFloaters(){let w=0;for(let i=0;i<floaters.length;i++){const f=floaters[i];if(f.t<f.dur)floaters[w++]=f;else fPool.push(f);}floaters.length=w;}
/* ================= 路径/迷宫 ================= */
const WP=[[-1,2],[3,2],[3,7],[7,7],[7,2],[11,2],[11,8],[14,8],[14,4],[16.5,4]];
const START=[0,2],GOAL=[15,4];
function gridFromCorners(corners){const g=[];for(let i=0;i<corners.length-1;i++){let[c1,r1]=corners[i],[c2,r2]=corners[i+1];c1=clamp(c1,0,COLS-1);c2=clamp(c2,0,COLS-1);r1=clamp(r1,0,ROWS-1);r2=clamp(r2,0,ROWS-1);const dc=Math.sign(c2-c1),dr=Math.sign(r2-r1);let c=c1,r=r1;while(true){if(!g.length||g[g.length-1][0]!==c||g[g.length-1][1]!==r)g.push([c,r]);if(c===c2&&r===r2)break;c+=dc;r+=dr;}}return g;}
let gridPath=gridFromCorners(WP);
const origSet=new Set(gridPath.map(c=>c[0]+','+c[1]));
let pts=[],segs=[],totalLen=0,pathCells=new Set();
function buildPath(){pts=[{x:-25,y:(gridPath[0][1]+.5)*CELL}];for(const[c,r]of gridPath)pts.push({x:(c+.5)*CELL,y:(r+.5)*CELL});pts.push({x:W+25,y:(gridPath[gridPath.length-1][1]+.5)*CELL});segs=[];totalLen=0;for(let i=0;i<pts.length-1;i++){const a=pts[i],b=pts[i+1],len=Math.hypot(b.x-a.x,b.y-a.y);segs.push({x1:a.x,y1:a.y,x2:b.x,y2:b.y,len,cum:totalLen,a:Math.atan2(b.y-a.y,b.x-a.x)});totalLen+=len;}pathCells=new Set(gridPath.map(c=>c[0]+','+c[1]));}
buildPath();
function posAt(d){d=clamp(d,0,totalLen-.001);let s=segs[0];for(const sg of segs){if(d>=sg.cum&&d<=sg.cum+sg.len){s=sg;break;}}const k=(d-s.cum)/s.len;return{x:s.x1+(s.x2-s.x1)*k,y:s.y1+(s.y2-s.y1)*k,a:s.a};}
const DECOS=[{c:0,r:0,type:'tree',seed:1},{c:15,r:0,type:'tree',seed:4},{c:9,r:5,type:'rock',seed:2},{c:1,r:9,type:'shroom',seed:0},{c:13,r:1,type:'shroom',seed:3}];
const decoCells=new Set(DECOS.map(d=>d.c+','+d.r));
function astar(){const blocked=(c,r)=>c<0||c>=COLS||r<0||r>=ROWS||decoCells.has(c+','+r)||occ.has(c+','+r)||walls.has(c+','+r);const W2=12,sk=START[0]+','+START[1],gk=GOAL[0]+','+GOAL[1];const open=[sk],came={},gScore={[sk]:0},fScore={[sk]:0};const inOpen=new Set([sk]);const h=(c,r)=>Math.abs(c-GOAL[0])+Math.abs(r-GOAL[1]);while(open.length){let bi=0;for(let i=1;i<open.length;i++)if((fScore[open[i]]||1e9)<(fScore[open[bi]]||1e9))bi=i;const cur=open[bi];open.splice(bi,1);inOpen.delete(cur);if(cur===gk){const path=[];let k=cur;while(k){const p=k.split(',');path.unshift([+p[0],+p[1]]);k=came[k];}return path;}const[cc,cr]=cur.split(',').map(Number);const nb=[[cc+1,cr],[cc-1,cr],[cc,cr+1],[cc,cr-1]];for(const[nc,nr]of nb){if(blocked(nc,nr))continue;const nk=nc+','+nr;const w=origSet.has(nk)?1:W2;const tent=gScore[cur]+w;if(tent<(gScore[nk]??1e9)){came[nk]=cur;gScore[nk]=tent;fScore[nk]=tent+h(nc,nr);if(!inOpen.has(nk)){open.push(nk);inOpen.add(nk);}}}}return null;}
function recomputePath(){const np=astar();if(!np)return false;gridPath=np;buildPath();return true;}
