const SEASON_NAMES=['萤月','霜翎','熔金','翠潮','夜歌','磐石','流火','苍岚','岚起','星垂','露凝','焰息'];
function dateStr(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function shortDate(){const d=new Date();return(d.getMonth()+1)+'/'+d.getDate();}
function fmtDateCN(s){const p=s.split('-');return(+p[1])+'月'+(+p[2])+'日';}
function fmtTime(s){return Math.floor(s/60)+'′'+String(s%60).padStart(2,'0')+'″';}
function seedFromDate(ds){let h=2166136261;for(let i=0;i<ds.length;i++){h^=ds.charCodeAt(i);h=Math.imul(h,16777619)>>>0;}return h||123456;}
function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
function seasonInfo(){const now=new Date(),start=new Date(now.getFullYear(),0,1),doy=Math.floor((now-start)/86400000),idx=Math.floor(doy/14);return{id:now.getFullYear()+'-S'+(idx+1),name:'S'+(idx+1)+' · '+SEASON_NAMES[idx%SEASON_NAMES.length],daysLeft:14-(doy%14)};}
function weekStartStr(){const d=new Date(),day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return d.getFullYear()+'-W'+String(d.getMonth()+1).padStart(2,'0')+String(d.getDate()).padStart(2,'0');}
