function rollWeekly(){const ws=weekStartStr(),seed=seedFromDate(ws),r=mulberry32(seed);const bases=['boss','golem','titan'],base=bases[Math.floor(r()*3)];const pool=[...AFFIXES],af=[pool.splice(Math.floor(r()*pool.length),1)[0],pool.splice(Math.floor(r()*pool.length),1)[0]];const resists=['ice','shock','poison','fire'],resist=resists[Math.floor(r()*4)];return{week:ws,base,affixes:af,resist,name:ENEMIES[base].name};}
