function masterLv(k){const e=records.mastery[k]||0;return Math.min(10,Math.floor(Math.sqrt(e/40)));}
function masterMul(k){return 1+0.025*masterLv(k);}
function shrineMul(){return 1+0.06*shrineLv;}
function rollDaily(){const ds=dateStr(),seed=seedFromDate(ds),r0=mulberry32(seed),pool=[...MUTS],picked=[];for(let i=0;i<2;i++)picked.push(pool.splice(Math.floor(r0()*pool.length),1)[0]);const m={gold:230,lives:20,hp:1,spd:1,rw:1,cost:1};picked.forEach(p=>p.apply(m));dailyInfo={date:ds,seed,muts:picked,m};const d=new Date();$('dcDate').textContent=(d.getMonth()+1)+'月'+d.getDate()+'日 · '+WEEK[d.getDay()]+' · 每日刷新';$('dcMuts').innerHTML=picked.map(p=>'<span class="mutchip"><b>'+p.name+'</b>'+p.desc+'</span>').join('');}
function checkSeason(){const si=seasonInfo();if(records.season.id&&records.season.id!==si.id){records.season.archive.unshift({name:records.season.name||records.season.id,lvl:records.season.lvl,best:records.season.bestEndless||0});records.season.archive=records.season.archive.slice(0,4);records.season.xp=0;records.season.lvl=0;records.season.bestEndless=0;seasonNew=true;}records.season.id=si.id;records.season.name=si.name;saveRecords();}
function addSeasonXP(n){if(n<=0)return;const s=records.season;let lv=false;s.xp+=n;while(s.lvl<10&&s.xp>=xpNeed(s.lvl)){s.xp-=xpNeed(s.lvl);s.lvl++;lv=true;}if(s.lvl>=10)s.xp=Math.min(s.xp,xpNeed(10));saveRecords();if(lv){toast('赛季等级提升 · Lv.'+s.lvl);const rw=SEASON_REWARDS.find(r=>r.lvl===s.lvl);if(rw)setTimeout(()=>toast('解锁赛季皮肤 · '+skinName(rw.skin)),1900);}}
function curMods(){if(mode==='daily')return dailyInfo.m;const D=DIFFS[diff];return{hp:D.hp,spd:D.spd,rw:D.rw};}
function waveMul(d){let m=mode==='level'?(d.boss?1+(wave-1)*.05:1+(wave-1)*.13):(d.boss?1+(wave-1)*.10:1+(wave-1)*.16+Math.pow(Math.max(0,wave-12),1.55)*.06);if(coop)m*=d.boss?1.35:1.6;if(mode==='weekly')m*=d.boss?3:1;return m;}
function costMulG(){return mode==='daily'?dailyInfo.m.cost:1;}
const costOf=d=>Math.round(d.cost*costMulG());
const upCost=t=>Math.round(Math.round(t.def.cost*.9*t.level)*costMulG());
function tStats(t){const d=t.def,m=t.level-1;return{dmg:Math.round(d.dmg*Math.pow(1.65,m)*masterMul(d.key)*shrineMul()),dmg2:d.dmg2?Math.round(d.dmg2*Math.pow(1.65,m)*masterMul(d.key)*shrineMul()):0,range:Math.round(d.range*Math.pow(d.proj==='sniper'?1.05:1.07,m))+shrineLv*5,rate:+(d.rate*Math.pow(1.12,m)).toFixed(2),chain:d.chain?d.chain+m:0,splash:d.splash?d.splash+m*8:0,slowF:d.slow?Math.max(.32,d.slow.f-m*.09):0,slowT:d.slow?d.slow.t+m*.5:0,psnDps:d.psn?Math.round(d.psn.dps*Math.pow(1.5,m)):0,psnDur:d.psn?+(d.psn.dur+m*.4).toFixed(1):0,psnMax:d.psn?d.psn.max+m:0,mineAmt:d.mine?Math.round(d.mine.amt*Math.pow(1.8,m)):0};}
function canPlace(c,r){return c>=0&&c<COLS&&r>=0&&r<ROWS&&!pathCells.has(c+','+r)&&!decoCells.has(c+','+r)&&!occ.has(c+','+r)&&!walls.has(c+','+r);}
function canPlaceWall(c,r){return c>=0&&c<COLS&&r>=0&&r<ROWS&&!pathCells.has(c+','+r)&&!decoCells.has(c+','+r)&&!occ.has(c+','+r)&&!walls.has(c+','+r);}
function seasonLvl(){return records.season?records.season.lvl:0;}
function skinUnlocked(k,sid){const s=SKINS[k].find(x=>x.id===sid);if(!s)return false;if(s.ach)return!!records.ach[s.ach];if(s.season)return seasonLvl()>=s.season;return true;}
function getPal(k){const list=SKINS[k];let id=records.eq[k]||list[0].id;if(!skinUnlocked(k,id))id=list[0].id;return PAL[k][id]||PAL[k][list[0].id];}
function skinName(ref){const p=ref.split(':'),s=(SKINS[p[0]]||[]).find(x=>x.id===p[1]);return(TOWERS[p[0]]?TOWERS[p[0]].name:'')+'「'+(s?s.name:'')+'」';}
function react(e,type,dmg){if(!e.reactCd)e.reactCd={};if(type==='explode'&&e.elem&&e.elem.frozen>0&&!(e.reactCd.shatter>0)){e.reactCd.shatter=.6;boom(e.x,e.y,dmg*.6,46);pushF(e.x,e.y-e.r-6,'碎冰!','#bfe3ff',.7,true);for(let i=0;i<6;i++)P(e.x,e.y,rnd(-40,40),rnd(-40,40),.4,'190,225,255',2);}if(type==='fire'&&e.elem&&e.elem.frozen>0&&!(e.reactCd.melt>0)){e.reactCd.melt=.6;const tr=Math.max(e.maxHp*.05,8);e.hp-=tr;pushF(e.x,e.y-e.r-6,'融化!','#ffd0b8',.7,true);for(let i=0;i<5;i++)P(e.x,e.y,rnd(-30,30),rnd(-40,0),.4,'255,180,120',2);if(e.hp<=0&&!e.dead){e.dead=true;onKill(e);}}if(type==='shock'&&e.psn&&e.psn.t>0&&!(e.reactCd.spread>0)){e.reactCd.spread=.6;let n=0;for(const o of enemies){if(o===e||o.dead||n>=2)continue;const dx=o.x-e.x,dy=o.y-e.y;if(dx*dx+dy*dy<70*70){applyPoison(o,{dps:e.psn.dps,dur:e.psn.dur,max:e.psn.max});hurt(o,dmg*.4,false,'shock');n++;pushF(o.x,o.y-o.r-4,'⚡','#fff3c9',.5,false);}}pushF(e.x,e.y-e.r-6,'传染!','#cfeaff',.7,true);}}
function setElem(e,type){if(!e.elem)e.elem={frozen:0,shocked:0,burn:0};if(type==='ice')e.elem.frozen=Math.max(e.elem.frozen,1.3);if(type==='shock')e.elem.shocked=.8;if(type==='fire'||type==='explode')e.elem.burn=Math.max(e.elem.burn,1.5);}
function rollAffix(e){const p=0.10+wave*0.012+(diff==='hard'?0.06:diff==='easy'?-0.04:0);if(Math.random()<p){const a=AFFIXES[Math.floor(Math.random()*AFFIXES.length)];e.affix=a;if(a==='shield')e.shield=e.maxHp*0.35;if(a==='swift')e.spd*=1.4;}}
function rebuildBuckets(){buckets.clear();for(const e of enemies){if(e.dead)continue;const k=(e.x/CELL|0)+','+(e.y/CELL|0);let b=buckets.get(k);if(!b){b=[];buckets.set(k,b);}b.push(e);}}
function acquire(t,st){let best=null,bv=-1;const rr2=st.range/CELL+1;const cx=t.x/CELL|0,cy=t.y/CELL|0;const r2=st.range*st.range;for(let gx=cx-rr2|0;gx<=cx+rr2;gx++)for(let gy=cy-rr2|0;gy<=cy+rr2;gy++){const b=buckets.get(gx+','+gy);if(!b)continue;for(const e of b){const dx=e.x-t.x,dy=e.y-t.y;if(dx*dx+dy*dy<=r2){const v=t.def.proj==='sniper'?e.hp:e.dist;if(v>bv){bv=v;best=e;}}}}return best;}
function achProg(a){const s=records.stats;switch(a.id){case 'a_kill10':return Math.min(s.kills,10)+'/10';case 'a_kill500':return Math.min(s.kills,500)+'/500';case 'a_e15':return Math.min(s.eBest||0,15)+'/15';case 'a_e30':return Math.min(s.eBest||0,30)+'/30';case 'a_daily5':return Math.min(s.dBest||0,5)+'/5';case 'a_daily15':return Math.min(s.dBest||0,15)+'/15';case 'a_necro10':return Math.min(s.necro||0,10)+'/10';case 'a_gold':return Math.min(Math.floor(runGold),3000)+'/3000';default:return null;}}
function checkAchs(){const s=records.stats,got=[];for(const a of ACHS){if(records.ach[a.id])continue;let ok=false;switch(a.id){case 'a_kill10':ok=s.kills>=10;break;case 'a_kill500':ok=s.kills>=500;break;case 'a_boss':ok=s.boss>0;break;case 'a_golem':ok=s.golem>0;break;case 'a_titan':ok=(s.titan||0)>0;break;case 'a_clear':ok=records.clears>0;break;case 'a_hard':ok=records.hardClears>0;break;case 'a_coop':ok=(records.coopClears||0)>0;break;case 'a_e15':ok=(s.eBest||0)>=15;break;case 'a_e30':ok=(s.eBest||0)>=30;break;case 'a_daily5':ok=(s.dBest||0)>=5;break;case 'a_daily15':ok=(s.dBest||0)>=15;break;case 'a_gold':ok=runGold>=3000;break;case 'a_lv3':ok=(s.lv3||0)>0;break;case 'a_all7':ok=new Set(towers.map(t=>t.key)).size>=ORDER.length;break;case 'a_mine3':ok=towers.filter(t=>t.key==='mine').length>=3;break;case 'a_necro10':ok=(s.necro||0)>=10;break;case 'a_boomK':ok=(s.boom8||0)>0;break;case 'a_laser':ok=(s.laser500||0)>0;break;}if(ok){records.ach[a.id]=true;got.push(a);}}if(got.length){saveRecords();got.forEach(achToast);}}
const achQueue=[];let achBusy=false;
function achToast(a){achQueue.push(a);pumpAch();}
function pumpAch(){if(achBusy||!achQueue.length)return;achBusy=true;const a=achQueue.shift();$('achToastName').textContent='成就达成 · '+a.name;$('achToastDesc').textContent=a.desc+(a.skin?' · 解锁皮肤 '+skinName(a.skin):'');const el=$('achToast');el.classList.add('show');sfx.clear();setTimeout(()=>{el.classList.remove('show');setTimeout(()=>{achBusy=false;pumpAch();},380);},3200);}
function gainGold(n){if(goldBuffT>0)n*=2;n=Math.round(n);gold+=n;runGold+=n;achDirty=true;}
function pushLB(b,e){records.lb[b].push(e);if(b==='endless')records.lb[b].sort((x,y)=>y.w-x.w||y.k-x.k);if(b==='level')records.lb[b].sort((x,y)=>x.t-y.t);records.lb[b]=records.lb[b].slice(0,b==='daily'?14:10);lbFlash={b};saveRecords();}
function upsertDailyLB(ds,w){const arr=records.lb.daily,ex=arr.find(e=>e.date===ds);if(ex)ex.w=Math.max(ex.w,w);else arr.push({date:ds,w});arr.sort((a,b)=>b.date.localeCompare(a.date));records.lb.daily=arr.slice(0,14);lbFlash={b:'daily'};saveRecords();}
