let AC=null,master=null,nbuf=null;
function audio(){try{if(!AC){AC=new(window.AudioContext||window.webkitAudioContext)();master=AC.createGain();master.gain.value=.4;master.connect(AC.destination);}if(AC.state==='suspended')AC.resume();}catch(e){}}
function tone(f0,f1,dur,type,vol){if(!AC||muted)return;try{const t0=AC.currentTime,o=AC.createOscillator(),g=AC.createGain();o.type=type;o.frequency.setValueAtTime(f0,t0);if(f1&&f1!==f0)o.frequency.exponentialRampToValueAtTime(Math.max(20,f1),t0+dur);g.gain.setValueAtTime(vol,t0);g.gain.exponentialRampToValueAtTime(.0001,t0+dur);o.connect(g);g.connect(master);o.start(t0);o.stop(t0+dur+.03);}catch(e){}}
function boomN(dur,vol,fc){if(!AC||muted)return;try{if(!nbuf){nbuf=AC.createBuffer(1,AC.sampleRate*.5,AC.sampleRate);const d=nbuf.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;}const s=AC.createBufferSource();s.buffer=nbuf;const f=AC.createBiquadFilter();f.type='lowpass';f.frequency.value=fc;const g=AC.createGain();const t0=AC.currentTime;g.gain.setValueAtTime(vol,t0);g.gain.exponentialRampToValueAtTime(.0001,t0+dur);s.connect(f);f.connect(g);g.connect(master);s.start(t0);s.stop(t0+dur);}catch(e){}}
let _sh=0,_co=0,_hi=0;
const sfx={shoot(){const n=performance.now();if(n-_sh<45)return;_sh=n;tone(760,420,.06,'square',.035);},hit(){const n=performance.now();if(n-_hi<60)return;_hi=n;tone(280,160,.05,'triangle',.05);},boom(){boomN(.28,.3,420);tone(110,36,.28,'sine',.3);},ice(){tone(1500,2100,.14,'sine',.05);tone(900,1300,.14,'sine',.04);},zap(){tone(1600,180,.13,'sawtooth',.06);boomN(.08,.12,3000);},sniper(){tone(1300,160,.16,'sawtooth',.08);boomN(.1,.18,2600);},coin(){const n=performance.now();if(n-_co<90)return;_co=n;tone(920,0,.06,'square',.05);setTimeout(()=>tone(1380,0,.09,'square',.05),55);},place(){tone(200,120,.14,'sine',.22);boomN(.08,.15,800);},up(){[520,660,880].forEach((f,i)=>setTimeout(()=>tone(f,0,.09,'square',.06),i*70));},sell(){tone(560,220,.16,'square',.06);},deny(){tone(190,120,.12,'square',.08);},wave(){tone(160,330,.45,'sawtooth',.1);tone(80,165,.45,'sawtooth',.08);},leak(){tone(330,80,.4,'sawtooth',.22);},clear(){[523,659,784].forEach((f,i)=>setTimeout(()=>tone(f,0,.12,'triangle',.08),i*90));},win(){[523,659,784,1046,1318].forEach((f,i)=>setTimeout(()=>tone(f,0,.22,'triangle',.1),i*130));},lose(){[392,311,262,196].forEach((f,i)=>setTimeout(()=>tone(f,0,.3,'sawtooth',.09),i*180));}};
document.addEventListener('pointerdown',audio);document.addEventListener('keydown',audio);
