let bgCan=null,gridCan=null;
function makeBG(){const c=document.createElement('canvas');c.width=W;c.height=H;const g=c.getContext('2d');const gr=g.createLinearGradient(0,0,0,H);gr.addColorStop(0,'#123128');gr.addColorStop(1,'#0c241c');g.fillStyle=gr;g.fillRect(0,0,W,H);const rg=g.createRadialGradient(W*.7,-60,40,W*.7,-60,520);rg.addColorStop(0,'rgba(130,210,170,.10)');rg.addColorStop(1,'rgba(0,0,0,0)');g.fillStyle=rg;g.fillRect(0,0,W,H);for(let i=0;i<430;i++){g.fillStyle=['rgba(20,53,40,.6)','rgba(9,30,22,.6)','rgba(28,66,49,.5)'][i%3];g.beginPath();g.arc(rnd(0,W),rnd(0,H),rnd(.8,2.6),0,7);g.fill();}g.strokeStyle='rgba(46,110,80,.5)';g.lineWidth=1;for(let i=0;i<150;i++){const x=rnd(0,W),y=rnd(0,H);for(let k=-1;k<=1;k++){g.beginPath();g.moveTo(x,y);g.quadraticCurveTo(x+k*2,y-4,x+k*3,y-rnd(5,8));g.stroke();}}for(let i=0;i<28;i++){g.fillStyle=i%4?'rgba(150,220,180,.5)':'rgba(255,210,120,.6)';g.beginPath();g.arc(rnd(0,W),rnd(0,H),1.4,0,7);g.fill();}const Pth=new Path2D();Pth.moveTo(pts[0].x,pts[0].y);for(let i=1;i<pts.length;i++)Pth.lineTo(pts[i].x,pts[i].y);g.lineJoin='round';g.lineCap='round';g.strokeStyle='#37322a';g.lineWidth=46;g.stroke(Pth);g.strokeStyle='#57503f';g.lineWidth=40;g.stroke(Pth);g.save();g.setLineDash([3,24]);g.lineDashOffset=rnd(0,20);g.strokeStyle='rgba(40,36,28,.55)';g.lineWidth=40;g.stroke(Pth);g.restore();g.strokeStyle='rgba(122,113,92,.35)';g.lineWidth=16;g.stroke(Pth);for(let d=0;d<totalLen;d+=rnd(18,34)){const p=posAt(d),off=rnd(20,26)*(Math.random()<.5?-1:1);const px=p.x-Math.sin(p.a)*off,py=p.y+Math.cos(p.a)*off;g.fillStyle='rgba(90,84,68,.8)';g.beginPath();g.arc(px,py,rnd(1.5,3),0,7);g.fill();}g.fillStyle='rgba(140,200,170,.10)';for(let cc=0;cc<=COLS;cc++)for(let rr2=0;rr2<=ROWS;rr2++){g.beginPath();g.arc(cc*CELL,rr2*CELL,1.1,0,7);g.fill();}const vg=g.createRadialGradient(W/2,H/2,H*.42,W/2,H/2,H*.9);vg.addColorStop(0,'rgba(0,0,0,0)');vg.addColorStop(1,'rgba(4,10,8,.55)');g.fillStyle=vg;g.fillRect(0,0,W,H);gridCan=document.createElement('canvas');gridCan.width=W;gridCan.height=H;const q=gridCan.getContext('2d');q.strokeStyle='rgba(110,190,160,.16)';q.lineWidth=1;for(let cc=0;cc<COLS;cc++)for(let rr2=0;rr2<ROWS;rr2++){if(pathCells.has(cc+','+rr2)||decoCells.has(cc+','+rr2))continue;q.strokeRect(cc*CELL+3.5,rr2*CELL+3.5,CELL-7,CELL-7);}return c;}
