  const w=e.def.boss?r*2.6:r*2.2,pct=clamp(e.hp/e.maxHp,0,1),bx=e.x-w/2,by=e.y-r-11+bob,bh=e.def.boss?6:4;
  g.fillStyle='rgba(6,14,10,.85)';rr(g,bx-1,by-1,w+2,bh+2,3);g.fill();g.fillStyle=pct>.5?'#7ee27e':pct>.25?'#ffd75e':'#ff6d5a';if(pct>0){rr(g,bx,by,w*pct,bh,2);g.fill();}
