    if(e.def.heal){e.healT-=dt;if(e.healT<=0){e.healT=.7;for(const o of enemies){if(o===e||o.dead)continue;const dx=o.x-e.x,dy=o.y-e.y;if(dx*dx+dy*dy<75*75&&o.hp<o.maxHp){o.hp=Math.min(o.maxHp,o.hp+e.def.heal);P(o.x+rnd(-4,4),o.y-o.r,rnd(-6,6),rnd(-24,-14),.6,'140,240,150',1.8);}}}}
    if(e.affix==='regen'||e.affix2==='regen'){e.regenT-=dt;if(e.regenT<=0){e.regenT=.5;e.hp=Math.min(e.maxHp,e.hp+e.maxHp*.02);}}
    if(e.def.summon){e.sumT-=dt;if(e.sumT<=0){e.sumT=4.5;if(enemies.length<70){spawnMinion('skel',e.dist-14);spawnMinion('skel',e.dist-24);for(let i=0;i<6;i++)P(e.x,e.y,rnd(-30,30),rnd(-40,10),.5,'176,166,201',2);pushF(e.x,e.y-e.r-6,'召唤!','#c9b8ff',.7,false);}}}
