const flies=Array.from({length:9},()=>({x:rnd(0,W),y:rnd(0,H),vx:rnd(-8,8),vy:rnd(-6,6),ph:rnd(0,6),r:rnd(1.5,2.6)}));
function drawRange(g,x,y,r,anim){g.beginPath();g.arc(x,y,r,0,7);g.fillStyle='rgba(79,227,178,.07)';g.fill();if(anim){g.setLineDash([6,6]);g.lineDashOffset=-tGlobal*24;}g.strokeStyle='rgba(79,227,178,.5)';g.lineWidth=1.5;g.stroke();g.setLineDash([]);}
function strokeJitter(g,b){g.beginPath();g.moveTo(b.pts[0].x,b.pts[0].y);for(let i=1;i<b.pts.length;i++){const p=b.pts[i],q=b.pts[i-1];g.lineTo((p.x+q.x)/2+rnd(-4,4),(p.y+q.y)/2+rnd(-4,4));g.lineTo(p.x,p.y);}g.stroke();}
function render(){ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,W,H);let sx=0,sy=0;if(shake>0){sx=rnd(-shake,shake);sy=rnd(-shake,shake);}ctx.save();ctx.translate(sx,sy);ctx.drawImage(bgCan,0,0);drawPortal(ctx);drawShrine(ctx);for(const d of DECOS)drawDeco(ctx,d);for(const[k]of walls){const p=k.split(',');drawWall(ctx,(+p[0]+.5)*CELL,(+p[1]+.5)*CELL);}if(placing)ctx.drawImage(gridCan,0,0);if(selected){const sr=tStats(selected).range;if(sr>0)drawRange(ctx,selected.x,selected.y,sr,true);}for(const t of towers){if(t===selected){ctx.strokeStyle='rgba(255,255,255,.55)';ctx.lineWidth=1.5;ctx.strokeRect(t.c*CELL+2,t.r*CELL+2,CELL-4,CELL-4);}drawTowerSprite(ctx,t.def,t.level,t.angle,t.recoil,t.x,t.y,1,t.seed);}enemies.sort((a,b)=>a.y-b.y);for(const e of enemies)drawEnemy(ctx,e);
  for(const t of towers){if(t.def.proj==='laser'&&t.lock&&!t.lock.dead){const k=Math.min((t.ramp||0)/3,1),x1=t.x+Math.cos(t.angle)*14,y1=t.y+Math.sin(t.angle)*14;ctx.globalAlpha=.22+.22*k;ctx.strokeStyle='#ff8c50';ctx.lineWidth=6+k*4;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(t.lock.x,t.lock.y);ctx.stroke();ctx.globalAlpha=1;ctx.strokeStyle=k>.6?'#ffd9b0':'#fff3e0';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(t.lock.x,t.lock.y);ctx.stroke();ctx.globalAlpha=.5+.3*Math.sin(tGlobal*30);ctx.fillStyle='#ffaa6e';ctx.beginPath();ctx.arc(t.lock.x,t.lock.y,4+k*3,0,7);ctx.fill();ctx.globalAlpha=1;}}
  for(const p of projectiles){if(p.kind==='boom'){ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.spin);ctx.strokeStyle=p.col||'#e8b46b';ctx.lineWidth=3;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-7,-4);ctx.quadraticCurveTo(0,-1,0,7);ctx.moveTo(7,-4);ctx.quadraticCurveTo(0,-1,0,7);ctx.stroke();ctx.restore();continue;}if(p.kind==='cannon'){drawGlow(ctx,p.x,p.y,8,p.col||'#ffb454',.5);ctx.beginPath();ctx.arc(p.x,p.y,4.5,0,7);ctx.fillStyle='#2b2f34';ctx.fill();ctx.strokeStyle='#111';ctx.lineWidth=1.5;ctx.stroke();continue;}if(p.kind==='spore'){drawGlow(ctx,p.x,p.y,7,p.col||'#9fe36b',.5);ctx.beginPath();ctx.arc(p.x,p.y,3.5,0,7);ctx.fillStyle=p.col||'#9fe36b';ctx.fill();ctx.strokeStyle='rgba(0,0,0,.35)';ctx.lineWidth=1.2;ctx.stroke();continue;}ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.a);if(p.kind==='arrow'){ctx.strokeStyle='#e8fff2';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-8,0);ctx.lineTo(4,0);ctx.stroke();ctx.fillStyle=p.col||'#7fd4c1';ctx.beginPath();ctx.arc(4,0,2,0,7);ctx.fill();}ctx.restore();}
  for(const b of beams){const a=1-b.t/b.dur;ctx.save();ctx.globalAlpha=a;ctx.strokeStyle='rgba(255,220,120,.35)';ctx.lineWidth=b.thin?3.5:6;strokeJitter(ctx,b);ctx.strokeStyle='#fff8e0';ctx.lineWidth=b.thin?1.4:2;strokeJitter(ctx,b);ctx.restore();}
  for(const r of rings){const k=r.t/r.dur;if(!r.col)r.col='rgb('+r.c+')';ctx.globalAlpha=1-k;ctx.strokeStyle=r.col;ctx.lineWidth=2.5;ctx.beginPath();ctx.arc(r.x,r.y,r.r0+(r.r1-r.r0)*k,0,7);ctx.stroke();}ctx.globalAlpha=1;
  for(const p of particles){const a=Math.max(0,1-p.t/p.dur)*.9;ctx.globalAlpha=a;ctx.fillStyle=p.c;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,7);ctx.fill();}ctx.globalAlpha=1;
  for(const f of flies){const a=.35+.45*(.5+.5*Math.sin(tGlobal*2+f.ph));drawGlow(ctx,f.x,f.y,f.r*4,'255,222,138',a);}
  drawWeather(ctx);
  ctx.textAlign='center';for(const f of floaters){const k=f.t/f.dur,a=k<.2?k/.2:1-(k-.2)/.8;ctx.globalAlpha=Math.max(0,a);ctx.font=f.big?FONT_B:FONT_S;ctx.strokeStyle='rgba(0,0,0,.6)';ctx.lineWidth=3;ctx.strokeText(f.txt,f.x,f.y);ctx.fillStyle=f.c;ctx.fillText(f.txt,f.x,f.y);}ctx.globalAlpha=1;
  if(placing&&mouse.in){const c=mouse.c,r=mouse.r;if(c>=0&&c<COLS&&r>=0&&r<ROWS){if(placing==='wall'){const ok=canPlaceWall(c,r)&&gold>=WALL.cost&&walls.size<14&&state!=='wave';ctx.fillStyle=ok?'rgba(120,200,120,.25)':'rgba(255,109,90,.25)';ctx.fillRect(c*CELL,r*CELL,CELL,CELL);ctx.globalAlpha=.8;drawWall(ctx,(c+.5)*CELL,(r+.5)*CELL);ctx.globalAlpha=1;}else{const ok=canPlace(c,r)&&gold>=costOf(TOWERS[placing]);const cx=(c+.5)*CELL,cy=(r+.5)*CELL,d=TOWERS[placing];ctx.fillStyle=ok?'rgba(79,227,178,.22)':'rgba(255,109,90,.22)';ctx.fillRect(c*CELL,r*CELL,CELL,CELL);if(d.range>0){ctx.beginPath();ctx.arc(cx,cy,d.range,0,7);ctx.fillStyle=ok?'rgba(79,227,178,.08)':'rgba(255,109,90,.08)';ctx.fill();ctx.strokeStyle=ok?'rgba(79,227,178,.55)':'rgba(255,109,90,.55)';ctx.lineWidth=1.5;ctx.stroke();}ctx.globalAlpha=.8;drawTowerSprite(ctx,d,1,-Math.PI/2,0,cx,cy,1,0);ctx.globalAlpha=1;}}}
  ctx.restore();}
/* ================= 页面萤火 ================= */
const bcv=document.getElementById('bgfx'),bx=bcv.getContext('2d');let bw,bh;const BGS=.5;
function resizeBG(){bw=bcv.width=Math.max(2,Math.floor(innerWidth*BGS));bh=bcv.height=Math.max(2,Math.floor(innerHeight*BGS));}resizeBG();addEventListener('resize',resizeBG);
const motes=Array.from({length:30},()=>({x:Math.random()*innerWidth*BGS,y:Math.random()*innerHeight*BGS,r:rnd(.8,1.8),ph:rnd(0,6),vx:rnd(-3,3),vy:rnd(-5,-1)}));
function drawBG(raw){bx.clearRect(0,0,bw,bh);for(const m of motes){m.x+=m.vx*raw;m.y+=m.vy*raw;if(m.y<-6){m.y=bh+6;m.x=Math.random()*bw}if(m.x<-6)m.x=bw+6;if(m.x>bw+6)m.x=-6;const a=.25+.45*(.5+.5*Math.sin(tGlobal*1.8+m.ph));drawGlow(bx,m.x,m.y,m.r*4,'255,218,130',a);}}
/* ================= UI ================= */
const $=id=>document.getElementById(id);
const waveBtn=$('waveBtn'),waveBarI=document.querySelector('#waveBar i');
const stGold=$('stGold'),stLife=$('stLife'),vGold=$('vGold'),vLife=$('vLife'),vWave=$('vWave');
const infoBody=$('infoBody'),ov=$('overlay'),ovBox=$('ovBox'),stage=$('stage'),menu=$('menu');
function banner(txt,cls){const elBanner=$('banner');elBanner.textContent=txt;elBanner.className='';void elBanner.offsetWidth;elBanner.className='show'+(cls?' '+cls:'');}
let toastT=null;function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastT);toastT=setTimeout(()=>el.classList.remove('show'),1800);}
const statCache={};
function setStat(wrap,id,val,anim){if(statCache[id]===val)return;const dec=typeof val==='number'&&statCache[id]!==undefined&&val<statCache[id];statCache[id]=val;$(id).textContent=val;if(anim!==false){wrap.classList.remove('pop');void wrap.offsetWidth;wrap.classList.add('pop');}if(anim&&dec){wrap.classList.remove('hurt');void wrap.offsetWidth;wrap.classList.add('hurt');}}
let _affKey='';
function syncUI(){setStat(stGold,'vGold',gold);setStat(stLife,'vLife',lives,true);const wv=mode==='level'?wave+'/'+WAVES.length:String(wave);if(vWave.textContent!==wv)vWave.textContent=wv;let key=(placing||'-')+costMulG()+walls.size;for(const k of ORDER)key+=gold<costOf(TOWERS[k])?'0':'1';key+=gold<WALL.cost?'w':'W';if(key!==_affKey){_affKey=key;document.querySelectorAll('.card').forEach(cd=>{const k=cd.dataset.k;cd.classList.toggle('sel',placing===k);if(k==='wall'){cd.classList.toggle('dis',gold<WALL.cost||walls.size>=14);}else{const cost=costOf(TOWERS[k]);cd.classList.toggle('dis',gold<cost);const cn=cd.querySelector('.ccost');if(cn.dataset.v!==String(cost)){cn.dataset.v=String(cost);cn.lastChild.nodeValue=String(cost);}}});}const ub=$('upBtn');if(ub&&selected)ub.disabled=selected.level>=3||gold<upCost(selected);}
let _lbl='',_bar=-1;
function updateWaveUI(){let label,dis=false,bar=0;if(state==='menu'){label='—';dis=true;}else if(state==='idle')label='⚔ 开始第 1 波';else if(state==='count'){const b=Math.ceil(countT*2.5);label='第 '+(wave+1)+' 波 · '+Math.ceil(countT)+'s 后来袭<small>点击提前召唤 +'+b+' 金</small>';bar=(1-countT/(mode==='level'?13:11))*100;}else if(state==='wave'){label='战斗中 · 剩余 '+(enemies.length+queue.length)+' 敌';dis=true;bar=100;}else{label='—';dis=true;}if(label!==_lbl){_lbl=label;waveBtn.innerHTML=label;waveBtn.disabled=dis;}if(Math.abs(bar-_bar)>.5){_bar=bar;waveBarI.style.width=bar+'%';}}
const skEls={};
['q','e','r','f'].forEach(id=>{const el=$('sk-'+id);skEls[id]={el,cd:el.querySelector('.cd'),em:el.querySelector('em'),last:-1,lastRdy:null,lastCool:null};el.addEventListener('pointerdown',e=>{e.preventDefault();audio();castSkill(id);});});
function updateSkillUI(){if(!coop)return;for(const id in skEls){const s=skEls[id],cd=skillState[id],tot=SKILLS[id].cd;const cooling=cd>0;if(cooling!==s.lastCool){s.lastCool=cooling;s.el.classList.toggle('cooling',cooling);}const frac=cooling?cd/tot:0;const deg=Math.round(frac*360);if(deg!==s.last){s.last=deg;s.cd.style.background='conic-gradient(rgba(4,12,9,.82) '+deg+'deg, transparent 0deg)';s.em.textContent=cooling?Math.ceil(cd):'';}const rdy=!cooling&&state==='wave';if(rdy!==s.lastRdy){s.lastRdy=rdy;s.el.classList.toggle('rdy',rdy);}}}
function traits(d){let s='';if(d.armor)s+='<em>甲'+d.armor+'</em>';if(d.slowImmune)s+='<em>免缓</em>';if(d.heal)s+='<em>疗</em>';if(d.split)s+='<em>分裂</em>';if(d.summon)s+='<em>召唤</em>';if(d.boss)s+='<em>首领</em>';return s;}
function waveChips(w){const def=getWaveDef(w),comp={};def.forEach(g=>comp[g.t]=(comp[g.t]||0)+g.count);return Object.entries(comp).map(([k,n])=>{const d=ENEMIES[k];return'<span class="chip'+(d.boss?' boss':'')+'"><i style="background:'+d.color+';box-shadow:0 0 8px '+d.color+'"></i>'+d.name+' ×'+n+traits(d)+'</span>';}).join('');}
function intelHTML(){let h='';const cur=state==='wave'?wave:wave+1;const rows=[['本波',cur],['下波',cur+1],['下下波',cur+2]];for(const[t,w]of rows){if(mode==='level'&&w>WAVES.length)continue;h+='<div class="intel-t">'+t+' · 第 '+w+' 波</div><div class="chips">'+waveChips(w)+'</div>';}h+='<p class="tip">'+HINTS[wave%HINTS.length]+'</p>';return h;}
function statRows(st,nx,d){let h='<div class="irow"><span>伤害</span><b>'+st.dmg+(nx?' <i>→ '+nx.dmg+'</i>':'')+'</b></div><div class="irow"><span>射程</span><b>'+st.range+(nx?' <i>→ '+nx.range+'</i>':'')+'</b></div>';if(!d.dmg2)h+='<div class="irow"><span>射速</span><b>'+st.rate+'/s'+(nx?' <i>→ '+nx.rate+'/s</i>':'')+'</b></div>';if(d.dmg2)h+='<div class="irow"><span>灼烧</span><b>'+st.dmg+'~'+(st.dmg+st.dmg2)+'/秒</b></div>';if(d.proj==='boom')h+='<div class="irow"><span>穿刺</span><b>往返双重</b></div>';if(d.splash)h+='<div class="irow"><span>溅射</span><b>'+st.splash+'</b></div>';if(d.chain)h+='<div class="irow"><span>链击</span><b>'+st.chain+' 个</b></div>';if(d.slow)h+='<div class="irow"><span>减速</span><b>'+Math.round((1-st.slowF)*100)+'%</b></div>';if(d.psn)h+='<div class="irow"><span>毒素</span><b>'+st.psnDps+'/s×'+st.psnMax+'</b></div>';if(d.mine)h+='<div class="irow"><span>产出</span><b>'+st.mineAmt+'/2.2s</b></div>';if(d.elem&&d.elem!=='phys')h+='<div class="irow"><span>元素</span><b>'+{ice:'冰',shock:'电',poison:'毒',fire:'火',explode:'爆'}[d.elem]+'</b></div>';return h;}
function renderInfo(){if(selected){const t=selected,d=t.def,st=tStats(t),nx=t.level<3?tStats({def:d,level:t.level+1}):null;const me=records.mastery[d.key]||0,ml=masterLv(d.key),mnxt=Math.pow(ml+1,2)*40;infoBody.innerHTML='<div class="sel-head"><span class="dot" style="background:'+d.color+';box-shadow:0 0 8px '+d.color+'"></span><b>'+d.name+'</b><span class="lv">'+'★'.repeat(t.level)+'☆'.repeat(3-t.level)+'</span></div>'+statRows(st,nx,d)+'<div class="irow"><span>精通 Lv.'+ml+'</span><b>+'+Math.round((masterMul(d.key)-1)*100)+'%</b></div><div class="mbar"><i style="width:'+Math.min(100,me/mnxt*100)+'%"></i></div>'+(d.elem&&d.elem!=='phys'?'<div class="irow"><span>元素联动</span><b>'+{ice:'冰+爆/火',shock:'电+毒',poison:'毒+电',fire:'火+冰',explode:'爆+冰'}[d.elem]+'</b></div>':'')+'<div class="iacts"><button class="btn up" id="upBtn" data-act="up" '+(t.level>=3?'disabled':'')+'>'+(t.level>=3?'已满级':'升级 ⬆ '+upCost(t))+'</button><button class="btn sell" data-act="sell">出售 +'+Math.round(t.invested*.7)+'</button></div>';syncUI();}else if(placing){if(placing==='wall'){infoBody.innerHTML='<div class="sel-head"><span class="dot" style="background:#7a5a3a"></span><b>荆棘桩 · 蓝图</b></div><div class="irow"><span>作用</span><b>阻挡改道敌军</b></div><div class="irow"><span>限制</span><b>仅战斗间隙布置</b></div><div class="irow"><span>数量</span><b>'+walls.size+'/14</b></div><p class="tip">放置后路径自动绕行 · 右键拆除返还 15 金</p>';}else{const d=TOWERS[placing],st=tStats({def:d,level:1});infoBody.innerHTML='<div class="sel-head"><span class="dot" style="background:'+d.color+';box-shadow:0 0 8px '+d.color+'"></span><b>'+d.name+' · 蓝图</b></div>'+statRows(st,null,d)+'<p class="tip">点击草地放置 · 右键或 Esc 取消</p>';}}else{infoBody.innerHTML=intelHTML()+'<div class="shrinebox"><span class="si">祭坛 Lv.'+shrineLv+'</span><span class="sb2">光环 +'+Math.round((shrineMul()-1)*100)+'% 伤害</span><button class="sbtn" id="shrineUp" '+(shrineLv>=3||gold>=[80,160,320][shrineLv]===false?'':'')+(shrineLv>=3||gold<[80,160,320][shrineLv]?'disabled':'')+'>⬆'+(shrineLv>=3?'满':[80,160,320][shrineLv])+'</button><button class="sbtn pulse" id="shrinePulse" '+(shrinePulseCd>0?'disabled':'')+'>'+(shrinePulseCd>0?Math.ceil(shrinePulseCd)+'s':'脉冲')+'</button></div>';}}
infoBody.addEventListener('click',e=>{const b=e.target.closest('[data-act]');if(b&&selected){if(b.dataset.act==='up'){const c=upCost(selected);if(selected.level<3&&gold>=c){gold-=c;selected.level++;selected.invested+=c;if(selected.level===3){records.stats.lv3=(records.stats.lv3||0)+1;markRecDirty();achDirty=true;}sfx.up();rings.push({x:selected.x,y:selected.y,r0:6,r1:34,t:0,dur:.45,c:'255,215,120'});for(let i=0;i<8;i++)P(selected.x,selected.y,rnd(-40,40),rnd(-70,-20),.6,'255,215,120',2,120);syncUI();renderInfo();}}else if(b.dataset.act==='sell'){const ref=Math.round(selected.invested*.7);gold+=ref;occ.delete(selected.c+','+selected.r);towers=towers.filter(t=>t!==selected);pushF(selected.x,selected.y-14,'+'+ref,'#ffd75e',.9,true);sfx.sell();selected=null;syncUI();renderInfo();}return;}const su=e.target.closest('#shrineUp');if(su){const c=[80,160,320][shrineLv];if(shrineLv<3&&gold>=c){gold-=c;shrineLv++;sfx.up();toast('祭坛升级 · Lv.'+shrineLv);syncUI();renderInfo();}return;}const sp=e.target.closest('#shrinePulse');if(sp){shrinePulse();renderInfo();return;}});
const cardsEl=$('cards');
ORDER.forEach((k,i)=>{const d=TOWERS[k];const div=document.createElement('div');div.className='card';div.dataset.k=k;div.innerHTML='<canvas class="cico" width="48" height="48"></canvas><div class="cinfo"><b>'+d.name+'</b><span>'+d.desc+'</span></div><div class="ccost"><i></i>'+d.cost+'</div><em class="ckey">'+(i+1)+'</em><em class="cms"></em>';div.addEventListener('click',()=>{audio();placing=placing===k?null:k;selected=null;cv.classList.toggle('placing',!!placing);syncUI();renderInfo();});cardsEl.appendChild(div);});
(function(){const div=document.createElement('div');div.className='card';div.dataset.k='wall';div.innerHTML='<canvas class="cico" width="48" height="48"></canvas><div class="cinfo"><b>荆棘桩</b><span>改道</span></div><div class="ccost"><i></i>'+WALL.cost+'</div><em class="ckey">0</em>';div.addEventListener('click',()=>{audio();placing=placing==='wall'?null:'wall';selected=null;cv.classList.toggle('placing',!!placing);syncUI();renderInfo();});cardsEl.appendChild(div);})();
function renderIcons(){document.querySelectorAll('.card').forEach(cd=>{const k=cd.dataset.k,g=cd.querySelector('canvas').getContext('2d');g.clearRect(0,0,48,48);if(k==='wall'){drawWall(g,24,27);}else{drawTowerSprite(g,TOWERS[k],1,-Math.PI/2,0,24,27,.92,1);}const ms=cd.querySelector('.cms');if(ms&&k!=='wall')ms.textContent=masterLv(k)>0?masterLv(k):'';});}
if(document.fonts&&document.fonts.ready)document.fonts.ready.then(renderIcons);else renderIcons();
function closeMeta(){['skinsOv','achOv','lbOv','seasonOv','helpOv','logOv'].forEach(id=>$(id).classList.remove('show'));}
function openSkins(){renderSkinsOv();$('skinsOv').classList.add('show');}
function renderSkinsOv(){const eq={};ORDER.forEach(k=>eq[k]=records.eq[k]||SKINS[k][0].id);$('skinsBody').innerHTML=ORDER.map(k=>{const d=TOWERS[k];const chips=SKINS[k].map(s=>{const un=skinUnlocked(k,s.id),isEq=un&&eq[k]===s.id;return'<button class="skinchip'+(isEq?' eq':'')+(un?'':' lock')+'" data-k="'+k+'" data-s="'+s.id+'" '+(un?'':'disabled')+'>'+(un?'':'<span class="lk">锁</span>')+'<canvas width="44" height="44" data-k="'+k+'" data-s="'+s.id+'"></canvas><span>'+s.name+'</span>'+(un?(isEq?'<em>已装备</em>':'<em style="color:var(--mut)">装备</em>'):'<em>'+(s.ach?'成就':'赛季Lv.'+s.season)+'</em>')+'</button>';}).join('');return'<div class="skinrow"><div class="skint"><canvas width="48" height="48" data-k="'+k+'" data-cur="1"></canvas><b>'+d.name+'</b></div><div class="skinchips">'+chips+'</div></div>';}).join('');$('skinsBody').querySelectorAll('canvas').forEach(c=>{const g=c.getContext('2d'),k=c.dataset.k,pal=c.dataset.cur?getPal(k):PAL[k][c.dataset.s];drawTowerSprite(g,TOWERS[k],1,-Math.PI/2,0,c.width/2,c.height/2+3,.8,1,pal);});}
$('skinsBody').addEventListener('click',e=>{const b=e.target.closest('.skinchip');if(!b||b.disabled)return;const k=b.dataset.k,s=b.dataset.s;if(!skinUnlocked(k,s))return;records.eq[k]=s;saveRecords();renderSkinsOv();renderIcons();const sk=SKINS[k].find(x=>x.id===s);toast('已装备 · '+TOWERS[k].name+'「'+sk.name+'」');});
function renderAchOv(){$('achBody').innerHTML=ACHS.map(a=>{const un=!!records.ach[a.id],sk=a.skin?skinName(a.skin):null,pg=un?'已达成':(achProg(a)||'未达成');return'<div class="achrow'+(un?' un':'')+'"><span class="abadge">'+(un?'成':'封')+'</span><div><b>'+a.name+'</b><span>'+a.desc+'</span>'+(sk?'<i>奖励皮肤:'+sk+'</i>':'')+'</div><em>'+pg+'</em></div>';}).join('');}
function renderLB(b){const lb=records.lb;let html='';const row=(rank,val,tag,sub,date,isNew)=>'<div class="lbrow'+(isNew?' new':'')+'">'+(rank?'<span class="lbrank r'+rank+'">'+rank+'</span>':'<span class="lbrank">·</span>')+'<span class="lbval">'+val+'</span>'+(tag?'<span class="lbdiff">'+tag+'</span>':'')+(sub?'<span class="lbsub">'+sub+'</span>':'')+'<span class="lbdate">'+date+'</span></div>';const empty=t=>'<div class="lbempty">'+t+'</div>';if(b==='endless')html=lb.endless.length?lb.endless.map((e,i)=>row(i+1,'第 '+e.w+' 波',DIFFS[e.d]?DIFFS[e.d].name:e.d,e.k+' 击杀',e.date,i===0&&lbFlash&&lbFlash.b==='endless')).join(''):empty('暂无记录');else if(b==='daily')html=lb.daily.length?lb.daily.map(e=>row(null,'第 '+e.w+' 波',e.date===dailyInfo.date?'今日':'','',fmtDateCN(e.date),false)).join(''):empty('暂无记录');else html=lb.level.length?lb.level.map((e,i)=>row(i+1,fmtTime(e.t),DIFFS[e.d]?DIFFS[e.d].name:e.d,'',e.date,i===0&&lbFlash&&lbFlash.b==='level')).join(''):empty('暂无记录');$('lbBody').innerHTML=html;}
function renderSeasonOv(){const si=seasonInfo(),s=records.season;$('seasonTitle').textContent='赛季 · '+si.name;$('seasonSub').textContent='剩余 '+si.daysLeft+' 天 · 每波结算与胜负获得赛季经验';$('sLvl').textContent='Lv.'+s.lvl;const need=xpNeed(s.lvl);$('sXpBar').style.width=(s.lvl>=10?100:Math.min(100,s.xp/need*100))+'%';$('sXpTxt').textContent=s.lvl>=10?'已满级':Math.floor(s.xp)+' / '+need;$('sTrack').innerHTML=SEASON_REWARDS.map(r=>{const un=s.lvl>=r.lvl;return'<div class="snode'+(un?' un':'')+'"><span class="slv-n">Lv.'+r.lvl+'</span><canvas width="44" height="44" data-skin="'+r.skin+'"></canvas><span class="sname">'+skinName(r.skin)+'</span>'+(un?'':'<span class="slock">未解锁</span>')+'</div>';}).join('');$('sTrack').querySelectorAll('canvas').forEach(c=>{const p=c.dataset.skin.split(':'),g=c.getContext('2d');drawTowerSprite(g,TOWERS[p[0]],1,-Math.PI/2,0,22,25,.8,1,PAL[p[0]][p[1]]);});$('sBest').innerHTML='本赛季无尽最佳<b>'+(s.bestEndless||0)+' 波</b>';$('sArch').innerHTML=(s.archive&&s.archive.length)?'<div class="sarch-t">历史赛季</div>'+s.archive.map(a=>'<div class="sarchrow"><span>'+a.name+'</span><span>Lv.'+a.lvl+'</span><span>最佳 '+a.best+' 波</span></div>').join(''):'';}
function renderHelp(){$('helpBody').innerHTML=HELP.map(h=>'<div class="helprow"><b>'+h[0]+'</b><span>'+h[1]+'</span></div>').join('');}
