function diffLine(d){const D=DIFFS[d];return'生命 '+D.lives+' · 起始 '+D.gold+' 金 · 敌血 '+Math.round(D.hp*100)+'% · 敌速 '+Math.round(D.spd*100)+'% · 奖励 '+Math.round(D.rw*100)+'%';}
function refreshMenu(){$('recLevel').textContent=records.clears>0?'◆ 通关 ×'+records.clears+(records.hardClears?'(深渊 ×'+records.hardClears+')':''):'◆ 尚无通关记录';const eb=records.endlessBest[diff]||0;$('recEndless').textContent=eb>0?'◆ '+DIFFS[diff].name+'最佳 · 第 '+eb+' 波':'◆ '+DIFFS[diff].name+' · 尚无挑战记录';let tot=0,got=0;for(const k in SKINS)for(const s of SKINS[k])if(s.ach||s.season){tot++;if(skinUnlocked(k,s.id))got++;}$('skinCnt').textContent=got+'/'+tot;$('achCnt').textContent=ACHS.filter(a=>records.ach[a.id]).length+'/'+ACHS.length;const tb=(records.dailyBest&&records.dailyBest[dailyInfo.date])||0;$('dcRec').innerHTML=tb>0?'今日最佳<b>第 '+tb+' 波</b>':'今日最佳<b>虚位以待</b>';$('wkName').textContent='周常 · '+weeklyInfo.name;$('wkDate').textContent='本周刷新 · 抗性['+{ice:'冰',shock:'电',poison:'毒',fire:'火'}[weeklyInfo.resist]+'] · '+weeklyInfo.affixes.map(a=>AFFIX_NAME[a]).join('/');$('wkMuts').innerHTML='<span class="mutchip"><b>词缀</b>'+weeklyInfo.affixes.map(a=>AFFIX_NAME[a]).join(' ')+'</span>';const wb=records.weeklyBest[weeklyInfo.week];$('wkRec').innerHTML=wb?'最佳<b>'+fmtTime(wb)+'</b>':'最佳<b>待攻克</b>';const si=seasonInfo(),s=records.season;$('sbName').textContent=si.name;$('sbLvl').textContent='Lv.'+s.lvl;$('sbBar').style.width=(s.lvl>=10?100:Math.min(100,s.xp/xpNeed(s.lvl)*100))+'%';$('sbDays').textContent='剩 '+si.daysLeft+' 天 · 详情 →';$('logCnt').textContent=VERSION;$('logBtn').classList.toggle('fresh',records.logSeen!==VERSION);let sv=null;try{sv=JSON.parse(localStorage.getItem(SAVE_KEY))}catch(e){}const cb=$('contBtn');if(sv&&sv.v===1){cb.style.display='inline-block';const mn=sv.mode==='daily'?'每日':sv.mode==='endless'?'无尽':'关卡';cb.innerHTML='▶ 继续征程 · 第 '+((sv.wave|0)+1)+' 波<small>'+mn+(sv.mode!=='daily'?' · '+DIFFS[sv.diff&&DIFFS[sv.diff]?sv.diff:'normal'].name:'')+' · '+sv.gold+' 金</small>';}else cb.style.display='none';}
function showMenu(){placing=null;selected=null;cv.classList.remove('placing');$('skillbar').classList.remove('on');refreshMenu();menu.classList.add('show');state='menu';syncUI();}
function showOverlay(win){let title,sub,cls,newRec=false,s3;
  if(mode==='weekly'){const t=Math.round(runT),prev=records.weeklyBest[weeklyInfo.week];if(!prev||t<prev){records.weeklyBest[weeklyInfo.week]=t;newRec=true;}saveRecords();cls='win';title='周常攻克!';sub='用时 '+fmtTime(t)+(newRec?'':' · 最佳 '+fmtTime(records.weeklyBest[weeklyInfo.week]));s3='<div><b>'+fmtTime(records.weeklyBest[weeklyInfo.week])+'</b><span>最佳用时</span></div>';}
  else if(mode==='endless'){const best=records.endlessBest;if(wave>(best[diff]||0)){best[diff]=wave;newRec=true;}records.stats.eBest=Math.max(records.stats.eBest||0,wave);if(wave>(records.season.bestEndless||0))records.season.bestEndless=wave;if(wave>=5)pushLB('endless',{w:wave,k:kills,d:diff,date:shortDate()});saveRecords();addSeasonXP(wave*3);cls='lose';title='深渊吞噬了祭坛…';sub='坚守至第 '+wave+' 波'+(newRec?'':' · '+DIFFS[diff].name+'最佳 第 '+(best[diff]||0)+' 波');s3='<div><b>'+(best[diff]||0)+'<i> 波</i></b><span>'+DIFFS[diff].name+'最佳</span></div>';}
  else if(mode==='daily'){const dstr=dailyInfo.date,prev=records.dailyBest[dstr]||0;if(wave>prev){records.dailyBest[dstr]=wave;newRec=true;}upsertDailyLB(dstr,wave);records.stats.dBest=Math.max(records.stats.dBest||0,wave);saveRecords();addSeasonXP(wave*3);cls='lose';title='今日挑战落幕';sub='坚守至第 '+wave+' 波 · '+dailyInfo.muts.map(m=>m.name).join(' / ')+(newRec?'':' · 今日最佳 第 '+records.dailyBest[dstr]+' 波');s3='<div><b>'+(records.dailyBest[dstr]||0)+'<i> 波</i></b><span>今日最佳</span></div>';}
  else{if(win){records.clears++;if(diff==='hard')records.hardClears=(records.hardClears||0)+1;if(coop)records.coopClears=(records.coopClears||0)+1;pushLB('level',{t:Math.round(runT),d:diff,date:shortDate()});saveRecords();addSeasonXP(100);cls='win';title='峡谷守住了!';sub='萤火祭坛的光芒,因你而长明。'+(coop?' 并肩作战的胜利!':'');}else{cls='lose';title='防线失守…';sub='巨像踏碎了祭坛的宁静……再试一次吧。';}s3='<div><b>'+Math.max(0,lives)+'</b><span>剩余生命</span></div>';}
  achDirty=true;ovBox.innerHTML='<h3 class="'+cls+'">'+title+'</h3><br>'+(newRec?'<div class="newrec">★ 新纪录!</div><br>':'')+'<p class="ovsub">'+sub+'</p><div class="ovstats"><div><b>'+kills+'</b><span>击杀敌人</span></div><div><b>'+wave+(mode==='level'?'<i>/'+WAVES.length+'</i>':'<i> 波</i>')+'</b><span>'+(mode==='level'?'抵达波次':'坚守波次')+'</span></div>'+s3+'</div><div class="ovbtns"><button class="btn gold" id="againBtn">⟳ 再战一局</button><button class="btn ghostbtn" id="menuBtn">返回主菜单</button></div>';ov.classList.add('show');$('againBtn').onclick=()=>{audio();const md=mode;ov.classList.remove('show');resetGame(md);banner(md==='endless'?'深渊开启':md==='daily'?'今日挑战':md==='weekly'?'周常攻克':'守住萤火祭坛!',md==='level'?'':'red');};$('menuBtn').onclick=()=>{audio();ov.classList.remove('show');resetGame('level');showMenu();};}
