function tryPlace(c,r){if(placing==='wall'){if(state==='wave'){toast('战斗间隙才能改道');sfx.deny();return;}if(!canPlaceWall(c,r)||walls.size>=14){sfx.deny();return;}if(gold<WALL.cost){pushF((c+.5)*CELL,(r+.5)*CELL,'金币不足','#ff8d7a',.9,false);sfx.deny();return;}walls.set(c+','+r,1);if(!recomputePath()){walls.delete(c+','+r);toast('此墙会堵死路径!');sfx.deny();buildPath();return;}gold-=WALL.cost;sfx.place();rings.push({x:(c+.5)*CELL,y:(r+.5)*CELL,r0:4,r1:24,t:0,dur:.4,c:'120,200,120'});achDirty=true;syncUI();return;}const d=TOWERS[placing];if(!canPlace(c,r)){sfx.deny();return;}const cost=costOf(d);if(gold<cost){pushF((c+.5)*CELL,(r+.5)*CELL,'金币不足','#ff8d7a',.9,false);sfx.deny();return;}gold-=cost;const t={key:placing,def:d,c,r,x:(c+.5)*CELL,y:(r+.5)*CELL,level:1,cool:0,angle:-Math.PI/2,recoil:0,ramp:0,lock:null,invested:cost,seed:rnd(0,7)};towers.push(t);occ.set(c+','+r,t);sfx.place();rings.push({x:t.x,y:t.y,r0:4,r1:30,t:0,dur:.4,c:'79,227,178'});for(let i=0;i<8;i++)P(t.x+rnd(-10,10),t.y+rnd(-6,10),rnd(-25,25),rnd(-40,-10),.5,'140,180,150',2,80);achDirty=true;syncUI();}
function setMouse(e){const rc=cv.getBoundingClientRect();mouse.x=(e.clientX-rc.left)*W/rc.width;mouse.y=(e.clientY-rc.top)*H/rc.height;mouse.c=Math.floor(mouse.x/CELL);mouse.r=Math.floor(mouse.y/CELL);mouse.in=true;}
cv.addEventListener('pointermove',setMouse);cv.addEventListener('pointerdown',setMouse);cv.addEventListener('mouseleave',()=>mouse.in=false);
cv.addEventListener('click',e=>{audio();setMouse(e);if(state==='menu'||state==='won'||state==='lost')return;if(placing){tryPlace(mouse.c,mouse.r);return;}const t=towers.find(t=>Math.abs(t.x-(mouse.c+.5)*CELL)<CELL*.6&&Math.abs(t.y-(mouse.r+.5)*CELL)<CELL*.6);if(t){selected=t;placing=null;cv.classList.remove('placing');}else{const wk=mouse.c+','+mouse.r;if(walls.has(wk)){selected=null;const ref=15;gold+=ref;walls.delete(wk);recomputePath();pushF((mouse.c+.5)*CELL,(mouse.r+.5)*CELL-14,'+'+ref,'#ffd75e',.9,true);sfx.sell();}else selected=null;}syncUI();renderInfo();});
cv.addEventListener('contextmenu',e=>{e.preventDefault();placing=null;selected=null;cv.classList.remove('placing');syncUI();renderInfo();});
document.addEventListener('touchmove',e=>{if(e.target.closest('.meta-in,.menu-box,#infoBody,.strack'))return;e.preventDefault();},{passive:false});
waveBtn.addEventListener('click',()=>{if(state==='idle'||state==='count')startWave();});
addEventListener('keydown',e=>{if(e.repeat)return;const k=e.key;if(['skinsOv','achOv','lbOv','seasonOv','helpOv','logOv'].some(id=>$(id).classList.contains('show'))){if(k==='Escape'||k===' '||k==='h'||k==='H')closeMeta();return;}if(k==='h'||k==='H'){renderHelp();$('helpOv').classList.toggle('show');return;}if(k>='1'&&k<='9'&&+k<=ORDER.length){const key=ORDER[+k-1];placing=placing===key?null:key;selected=null;cv.classList.toggle('placing',!!placing);syncUI();renderInfo();}else if(k==='0'){placing=placing==='wall'?null:'wall';selected=null;cv.classList.toggle('placing',!!placing);syncUI();renderInfo();}else if(k==='Escape'){placing=null;selected=null;cv.classList.remove('placing');syncUI();renderInfo();}else if(k===' '){e.preventDefault();if(state==='idle'||state==='count')startWave();}else if(k==='p'||k==='P')togglePause();else if(coop&&['q','e','r','f'].includes(k.toLowerCase()))castSkill(k.toLowerCase());});
function togglePause(){if(state!=='count'&&state!=='wave'&&state!=='idle')return;paused=!paused;stage.classList.toggle('paused',paused);$('pauseBtn').textContent=paused?'▶':'❚❚';if(paused){flushRecords();saveRun(true);}}
