function resetGame(md){mode=md||'level';genCache={};if(mode==='daily'){if(!dailyInfo)rollDaily();gold=dailyInfo.m.gold;lives=dailyInfo.m.lives;}else{const D=DIFFS[diff];gold=D.gold;lives=D.lives;}if(mode==='weekly'){weeklyInfo=rollWeekly();gold=300;lives=10;}livesCap=lives;wave=0;kills=0;runGold=0;runT=0;state='idle';countT=0;waveClock=0;queue=[];towers=[];enemies=[];projectiles=[];particles.length=0;floaters.length=0;beams=[];rings=[];occ.clear();walls.clear();gridPath=gridFromCorners(WP);buildPath();selected=null;placing=null;cv.classList.remove('placing');paused=false;stage.classList.remove('paused');$('pauseBtn').textContent='❚❚';shrineFlash=0;shake=0;goldBuffT=0;skillState={q:0,e:0,r:0,f:0};shrineLv=0;shrinePulseCd=0;weather='clear';$('weatherTag').classList.remove('on');ov.classList.remove('show');for(const k in statCache)delete statCache[k];_affKey='';const mt=$('modeTag');mt.textContent=mode==='endless'?'无尽深渊':mode==='daily'?'每日挑战':mode==='weekly'?'周常Boss':'关卡征程';mt.classList.toggle('ember',mode==='endless'||mode==='weekly');const dtg=$('diffTag');if(mode==='daily'||mode==='weekly'){dtg.textContent='挑战';dtg.className='';}else{dtg.textContent=DIFFS[diff].name;dtg.className=diff==='easy'?'t-easy':diff==='hard'?'t-hard':'';}$('coopTag').style.display=coop?'inline-block':'none';$('skillbar').classList.toggle('on',coop);$('waveNote').textContent=mode==='endless'?'无尽深渊 · 词缀多变,天气愈险':mode==='daily'?'今日规则 · '+dailyInfo.muts.map(m=>m.name+'('+m.desc+')').join(' · '):mode==='weekly'?'周常 · '+weeklyInfo.name+' · 抗性['+{ice:'冰',shock:'电',poison:'毒',fire:'火'}[weeklyInfo.resist]+']':'击退敌军获得金币 · 布墙设伏,元素联动';_lbl='';syncUI();renderInfo();renderIcons();}
