document.querySelectorAll('.diff').forEach(x=>x.classList.toggle('sel',x.dataset.d===diff));
$('diffInfo').textContent=diffLine(diff);$('coopBtn').classList.toggle('on',coop);$('coopState').textContent=coop?'已启用':'未启用';
