let last=performance.now();
function loop(now){requestAnimationFrame(loop);let raw=(now-last)/1000;last=now;if(raw>.05)raw=.05;tGlobal+=raw;const dt=(paused||state==='menu'||state==='won'||state==='lost')?0:raw*speed;update(dt,raw);render();drawBG(raw);updateWaveUI();updateSkillUI();if(achDirty){achDirty=false;checkAchs();}recT+=raw;if(recDirty&&recT>=1.5)flushRecords();}
